","import { MediaContentType } from "./api/api/index.js";
import { getGlobalLogger } from "./logger/index.js";
import { base64ToBytes, bytesToBase64 } from "./utils.js";

/**
 * Parameters for creating a LangfuseMedia instance.
 *
 * Supports two input formats:
 * - Base64 data URI (e.g., "data:image/png;base64,...")
 * - Raw bytes with explicit content type
 *
 * @public
 */
export type LangfuseMediaParams =
  | {
      /** Indicates the media is provided as a base64 data URI */
      source: "base64_data_uri";
      /** The complete base64 data URI string */
      base64DataUri: string;
    }
  | {
      /** Indicates the media is provided as raw bytes */
      source: "bytes";
      /** The raw content bytes */
      contentBytes: Uint8Array;
      /** The MIME type of the content */
      contentType: MediaContentType;
    };

/**
 * A class for wrapping media objects for upload to Langfuse.
 *
 * This class handles the preparation and formatting of media content for Langfuse,
 * supporting both base64 data URIs and raw content bytes. It automatically:
 * - Parses base64 data URIs to extract content type and bytes
 * - Generates SHA-256 hashes for content integrity
 * - Creates unique media IDs based on content hash
 * - Formats media references for embedding in traces
 *
 * @example
 * ```typescript
 * // From base64 data URI
 * const media1 = new LangfuseMedia({
 *   source: "base64_data_uri",
 *   base64DataUri: "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg=="
 * });
 *
 * // From raw bytes
 * const media2 = new LangfuseMedia({
 *   source: "bytes",
 *   contentBytes: new Uint8Array([72, 101, 108, 108, 111])
 *   contentType: "text/plain"
 * });
 *
 * console.log(media1.id); // Unique media ID
 * console.log(media1.tag); // Media reference tag
 * ```
 *
 * @public
 */
export class LangfuseMedia {
  _contentBytes?: Uint8Array;
  _contentType?: MediaContentType;
  _source?: string;

  /**
   * Creates a new LangfuseMedia instance.
   *
   * @param params - Media parameters specifying the source and content
   *
   * @example
   * ```typescript
   * // Create from base64 data URI
   * const media = new LangfuseMedia({
   *   source: "base64_data_uri",
   *   base64DataUri: "data:image/jpeg;base64,/9j/4AAQSkZJRgABAQAAAQ..."
   * });
   * ```
   */
  constructor(params: LangfuseMediaParams) {
    const { source } = params;

    this._source = source;

    if (source === "base64_data_uri") {
      const [contentBytesParsed, contentTypeParsed] = this.parseBase64DataUri(
        params.base64DataUri,
      );
      this._contentBytes = contentBytesParsed;
      this._contentType = contentTypeParsed;
    } else {
      this._contentBytes = params.contentBytes;
      this._contentType = params.contentType;
    }
  }

  /**
   * Parses a base64 data URI to extract content bytes and type.
   *
   * @param data - The base64 data URI string
   * @returns Tuple of [contentBytes, contentType] or [undefined, undefined] on error
   * @private
   */
  private parseBase64DataUri(
    data: string,
  ): [Uint8Array | undefined, MediaContentType | undefined] {
    try {
      if (!data || typeof data !== "string") {
        throw new Error("Data URI is not a string");
      }

      if (!data.startsWith("data:")) {
        throw new Error("Data URI does not start with 'data:'");
      }

      const [header, actualData] = data.slice(5).split(",", 2);
      if (!header || !actualData) {
        throw new Error("Invalid URI");
      }

      const headerParts = header.split(";");
      if (!headerParts.includes("base64")) {
        throw new Error("Data is not base64 encoded");
      }

      const contentType = headerParts[0];
      if (!contentType) {
        throw new Error("Content type is empty");
      }

      return [base64ToBytes(actualData), contentType as MediaContentType];
    } catch (error) {
      getGlobalLogger().error("Error parsing base64 data URI", error);
      return [undefined, undefined];
    }
  }

  /**
   * Gets a unique identifier for this media based on its content hash.
   *
   * The ID is derived from the first 22 characters of the URL-safe base64-encoded
   * SHA-256 hash of the content.
   *
   * @returns The unique media ID, or null if hash generation failed
   *
   * @example
   * ```typescript
   * const media = new LangfuseMedia({...});
   * console.log(media.id); // "A1B2C3D4E5F6G7H8I9J0K1"
   * ```
   */
  async getId(): Promise<string | null> {
    const contentSha256Hash = await this.getSha256Hash();
    if (!contentSha256Hash) return null;

    const urlSafeContentHash = contentSha256Hash
      .replaceAll("+", "-")
      .replaceAll("/", "_");

    return urlSafeContentHash.slice(0, 22);
  }

  /**
   * Gets the length of the media content in bytes.
   *
   * @returns The content length in bytes, or undefined if no content is available
   */
  get contentLength(): number | undefined {
    return this._contentBytes?.length;
  }

  /**
   * Gets the SHA-256 hash of the media content.
   *
   * The hash is used for content integrity verification and generating unique media IDs.
   * Returns undefined if crypto is not available or hash generation fails.
   *
   * @returns The base64-encoded SHA-256 hash, or undefined if unavailable
   */
  async getSha256Hash(): Promise<string | undefined> {
    if (!this._contentBytes) {
      return undefined;
    }

    try {
      const hash = await crypto.subtle.digest("SHA-256", this._contentBytes);

      return bytesToBase64(new Uint8Array(hash));
    } catch (error) {
      getGlobalLogger().warn(
        "[Langfuse] Failed to generate SHA-256 hash for media content:",
        error,
      );

      return undefined;
    }
  }

  /**
   * Gets the media reference tag for embedding in trace data.
   *
   * The tag format is: `@@@langfuseMedia:type=<contentType>|id=<mediaId>|source=<source>@@@`
   * This tag can be embedded in trace attributes and will be replaced with actual
   * media content when the trace is viewed in Langfuse.
   *
   * @returns The media reference tag, or null if required data is missing
   *
   * @example
   * ```typescript
   * const media = new LangfuseMedia({...});
   * console.log(media.tag);
   * // "@@@langfuseMedia:type=image/png|id=A1B2C3D4E5F6G7H8I9J0K1|source=base64_data_uri@@@"
   * ```
   */
  async getTag(): Promise<string | null> {
    const id = await this.getId();

    if (!this._contentType || !this._source || !id) return null;

    return `@@@langfuseMedia:type=${this._contentType}|id=${id}|source=${this._source}@@@`;
  }

  /**
   * Gets the media content as a base64 data URI.
   *
   * @returns The complete data URI string, or null if no content is available
   *
   * @example
   * ```typescript
   * const media = new LangfuseMedia({...});
   * console.log(media.base64DataUri);
   * // "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAAB..."
   * ```
   */
  get base64DataUri(): string | null {
    if (!this._contentBytes) return null;

    return `data:${this._contentType};base64,${bytesToBase64(this._contentBytes)}`;
  }

  /**
   * Serializes the media to JSON (returns the base64 data URI).
   *
   * @returns The base64 data URI, or null if no content is available
   */
  toJSON(): string | null {
    return this.base64DataUri;
  }
}
","/**
 * Attribute propagation utilities for Langfuse OpenTelemetry integration.
 *
 * This module provides the `propagateAttributes` function for setting trace-level
 * attributes (userId, sessionId, metadata) that automatically propagate to all child spans
 * within the context.
 */

import {
  context as otelContextApi,
  trace as otelTraceApi,
  propagation,
  Context,
  createContextKey,
} from "@opentelemetry/api";

import {
  LANGFUSE_SDK_EXPERIMENT_ENVIRONMENT,
  LangfuseOtelSpanAttributes,
} from "./constants.js";
import { getGlobalLogger } from "./logger/index.js";

type CorrelatedKey =
  | "userId"
  | "sessionId"
  | "metadata"
  | "version"
  | "tags"
  | "traceName";

const experimentKeys = [
  "experimentId",
  "experimentName",
  "experimentMetadata",
  "experimentDatasetId",
  "experimentItemId",
  "experimentItemMetadata",
  "experimentItemRootObservationId",
] as const;
type ExperimentKey = (typeof experimentKeys)[number];
type PropagatedKey = CorrelatedKey | ExperimentKey;

type PropagatedExperimentAttributes = {
  experimentId: string;
  experimentName: string;
  experimentMetadata?: string; // serialized JSON
  experimentDatasetId?: string;
  experimentItemId: string;
  experimentItemMetadata?: string; // serialized JSON
  experimentItemRootObservationId: string;
};

export const LangfuseOtelContextKeys: Record<PropagatedKey, symbol> = {
  userId: createContextKey("langfuse_user_id"),
  sessionId: createContextKey("langfuse_session_id"),
  metadata: createContextKey("langfuse_metadata"),
  version: createContextKey("langfuse_version"),
  tags: createContextKey("langfuse_tags"),
  traceName: createContextKey("langfuse_trace_name"),

  // Experiments
  experimentId: createContextKey("langfuse_experiment_id"),
  experimentName: createContextKey("langfuse_experiment_name"),
  experimentMetadata: createContextKey("langfuse_experiment_metadata"),
  experimentDatasetId: createContextKey("langfuse_experiment_dataset_id"),
  experimentItemId: createContextKey("langfuse_experiment_item_id"),
  experimentItemMetadata: createContextKey("langfuse_experiment_item_metadata"),
  experimentItemRootObservationId: createContextKey(
    "langfuse_experiment_item_root_observation_id",
  ),
};

const LANGFUSE_BAGGAGE_PREFIX = "langfuse_";
const LANGFUSE_BAGGAGE_TAGS_SEPARATOR = ",";

/**
 * Baggage key used by the SDK to claim that an upstream Langfuse-controlled
 * scope already exists for a given trace id. Downstream processors read this
 * to suppress duplicate app-root markers across services.
 *
 * @internal
 */
export const LANGFUSE_TRACE_ID_BAGGAGE_KEY = "langfuse_trace_id";

/**
 * Reads the Langfuse trace-id app-root claim from the baggage attached to a
 * context. Returns the lowercased trace id, or undefined if no claim exists.
 *
 * @internal
 */
export function getLangfuseTraceIdFromBaggage(
  context: Context,
): string | undefined {
  const baggage = propagation.getBaggage(context);
  const entry = baggage?.getEntry(LANGFUSE_TRACE_ID_BAGGAGE_KEY);

  if (!entry?.value) return undefined;

  return entry.value.toLowerCase();
}

/**
 * Returns a context that carries the Langfuse trace-id app-root claim in
 * baggage. If the context already carries the same claim, the original
 * context is returned unchanged so we don't churn baggage instances.
 *
 * @internal
 */
export function setLangfuseTraceIdInBaggage(
  context: Context,
  traceId: string,
): Context {
  const normalized = traceId.toLowerCase();

  if (getLangfuseTraceIdFromBaggage(context) === normalized) return context;

  const baggage =
    propagation.getBaggage(context) ?? propagation.createBaggage();
  const updated = baggage.setEntry(LANGFUSE_TRACE_ID_BAGGAGE_KEY, {
    value: normalized,
  });

  return propagation.setBaggage(context, updated);
}

/**
 * Parameters for propagateAttributes function.
 *
 * @public
 */
export interface PropagateAttributesParams {
  /**
   * User identifier to associate with all spans in this context.
   * Must be a string ≤200 characters. Use this to track which user
   * generated each trace and enable e.g. per-user cost/performance analysis.
   */
  userId?: string;

  /**
   * Session identifier to associate with all spans in this context.
   * Must be a string ≤200 characters. Use this to group related traces
   * within a user session (e.g., a conversation thread, multi-turn interaction).
   */
  sessionId?: string;

  /**
   * Additional key-value metadata to propagate to all spans.
   * - Keys and values must be strings
   * - All values must be ≤200 characters
   * - Use for dimensions like internal correlating identifiers
   * - AVOID: large payloads, sensitive data, non-string values (will be dropped with warning)
   */
  metadata?: Record<string, string>;

  /**
   * Version identifier for parts of your application that are independently versioned, e.g. agents
   */
  version?: string;

  /**
   * List of tags to categorize the group of observations
   */
  tags?: string[];

  /**
   * Trace name to associate with all spans in this context.
   * Must be a string ≤200 characters.
   */
  traceName?: string;

  /**
   * If true, propagates attributes using OpenTelemetry baggage for
   * cross-process/service propagation.
   *
   * **Security warning**: When enabled, attribute values are added to HTTP headers
   * on ALL outbound requests. Only enable if values are safe to transmit via HTTP
   * headers and you need cross-service tracing.
   *
   * @defaultValue false
   */
  asBaggage?: boolean;

  /**
   * **INTERNAL USE ONLY** - For Langfuse experiment framework.
   *
   * This parameter is used internally by the Langfuse experiment system to propagate
   * experiment context to child spans. It should NOT be used by external code.
   *
   * @internal
   */
  _internalExperiment?: PropagatedExperimentAttributes;
}

/**
 * Propagate trace-level attributes to all spans created within this context.
 *
 * This function sets attributes on the currently active span AND automatically
 * propagates them to all new child spans created within the callback. This is the
 * recommended way to set trace-level attributes like userId, sessionId, and metadata
 * dimensions that should be consistently applied across all observations in a trace.
 *
 * **IMPORTANT**: Call this as early as possible within your trace/workflow. Only the
 * currently active span and spans created after entering this context will have these
 * attributes. Pre-existing spans will NOT be retroactively updated.
 *
 * **Why this matters**: Langfuse aggregation queries (e.g., total cost by userId,
 * filtering by sessionId) only include observations that have the attribute set.
 * If you call `propagateAttributes` late in your workflow, earlier spans won't be
 * included in aggregations for that attribute.
 *
 * @param params - Configuration for attributes to propagate
 * @param fn - Callback function (sync or async) within which attributes are propagated
 * @returns The result of the callback function
 *
 * @example
 * Basic usage with user and session tracking:
 *
 * ```typescript
 * import { startActiveObservation, propagateAttributes } from '@langfuse/tracing';
 *
 * // Set attributes early in the trace
 * await startActiveObservation('user_workflow', async (span) => {
 *   await propagateAttributes({
 *     userId: 'user_123',
 *     sessionId: 'session_abc',
 *     metadata: { experiment: 'variant_a', environment: 'production' }
 *   }, async () => {
 *     // All spans created here will have userId, sessionId, and metadata
 *     const llmSpan = startObservation('llm_call', { input: 'Hello' });
 *     // This span inherits: userId, sessionId, experiment, environment
 *     llmSpan.end();
 *
 *     const gen = startObservation('completion', {}, { asType: 'generation' });
 *     // This span also inherits all attributes
 *     gen.end();
 *   });
 * });
 * ```
 *
 * @example
 * Late propagation (anti-pattern):
 *
 * ```typescript
 * await startActiveObservation('workflow', async (span) => {
 *   // These spans WON'T have userId
 *   const earlySpan = startObservation('early_work', { input: 'data' });
 *   earlySpan.end();
 *
 *   // Set attributes in the middle
 *   await propagateAttributes({ userId: 'user_123' }, async () => {
 *     // Only spans created AFTER this point will have userId
 *     const lateSpan = startObservation('late_work', { input: 'more' });
 *     lateSpan.end();
 *   });
 *
 *   // Result: Aggregations by userId will miss "early_work" span
 * });
 * ```
 *
 * @example
 * Cross-service propagation with baggage (advanced):
 *
 * ```typescript
 * import fetch from 'node-fetch';
 *
 * // Service A - originating service
 * await startActiveObservation('api_request', async () => {
 *   await propagateAttributes({
 *     userId: 'user_123',
 *     sessionId: 'session_abc',
 *     asBaggage: true  // Propagate via HTTP headers
 *   }, async () => {
 *     // Make HTTP request to Service B
 *     const response = await fetch('https://service-b.example.com/api');
 *     // userId and sessionId are now in HTTP headers
 *   });
 * });
 *
 * // Service B - downstream service
 * // OpenTelemetry will automatically extract baggage from HTTP headers
 * // and propagate to spans in Service B
 * ```
 *
 * @remarks
 * - **Validation**: All attribute values (userId, sessionId, metadata values)
 *   must be strings ≤200 characters. Invalid values will be dropped with a
 *   warning logged. Ensure values meet constraints before calling.
 * - **OpenTelemetry**: This uses OpenTelemetry context propagation under the hood,
 *   making it compatible with other OTel-instrumented libraries.
 * - **Baggage Security**: When `asBaggage=true`, attribute values are added to HTTP
 *   headers on outbound requests. Only use for non-sensitive values and when you
 *   need cross-service tracing.
 *
 * @public
 */
export function propagateAttributes<
  A extends unknown[],
  F extends (...args: A) => ReturnType<F>,
>(params: PropagateAttributesParams, fn: F): ReturnType<F> {
  let context = otelContextApi.active();

  const span = otelTraceApi.getActiveSpan();
  const asBaggage = params.asBaggage ?? false;

  const {
    userId,
    sessionId,
    metadata,
    version,
    tags,
    traceName,
    _internalExperiment,
  } = params;

  // Validate and set userId
  if (userId) {
    if (isValidPropagatedString({ value: userId, attributeName: "userId" })) {
      context = setPropagatedAttribute({
        key: "userId",
        value: userId,
        context,
        span,
        asBaggage,
      });
    }
  }

  // Validate and set sessionId
  if (sessionId) {
    if (
      isValidPropagatedString({
        value: sessionId,
        attributeName: "sessionId",
      })
    ) {
      context = setPropagatedAttribute({
        key: "sessionId",
        value: sessionId,
        context,
        span,
        asBaggage,
      });
    }
  }

  // Validate and set version
  if (version) {
    if (
      isValidPropagatedString({
        value: version,
        attributeName: "version",
      })
    ) {
      context = setPropagatedAttribute({
        key: "version",
        value: version,
        context,
        span,
        asBaggage,
      });
    }
  }

  // Validate and set traceName
  if (traceName) {
    if (
      isValidPropagatedString({
        value: traceName,
        attributeName: "traceName",
      })
    ) {
      context = setPropagatedAttribute({
        key: "traceName",
        value: traceName,
        context,
        span,
        asBaggage,
      });
    }
  }

  // Validate and set tags
  if (tags && tags.length > 0) {
    const validTags = tags.filter((tag) =>
      isValidPropagatedString({
        value: tag,
        attributeName: "tag",
      }),
    );

    if (validTags.length > 0) {
      context = setPropagatedAttribute({
        key: "tags",
        value: validTags,
        context,
        span,
        asBaggage,
      });
    }
  }

  // Validate and set metadata
  if (metadata) {
    // Filter metadata to only include valid string values
    const validatedMetadata: Record<string, string> = {};

    for (const [key, value] of Object.entries(metadata)) {
      if (
        isValidPropagatedString({
          value: value,
          attributeName: `metadata.${key}`,
        })
      ) {
        validatedMetadata[key] = value;
      }
    }

    if (Object.keys(validatedMetadata).length > 0) {
      context = setPropagatedAttribute({
        key: "metadata",
        value: validatedMetadata,
        context,
        span,
        asBaggage,
      });
    }
  }

  // Handle experiment attributes
  if (_internalExperiment) {
    for (const [key, value] of Object.entries(_internalExperiment)) {
      if (value !== undefined) {
        // Experiment attributes are already serialized, no validation needed
        context = setPropagatedAttribute({
          key: key as ExperimentKey,
          value,
          context,
          span,
          asBaggage,
        });
      }
    }
  }

  // Execute callback in the new context
  return otelContextApi.with(context, fn);
}

export function getPropagatedAttributesFromContext(
  context: Context,
): Record<string, string | string[]> {
  const propagatedAttributes: Record<string, string | string[]> = {};

  // Handle baggage
  const baggage = propagation.getBaggage(context);

  if (baggage) {
    baggage.getAllEntries().forEach(([baggageKey, baggageEntry]) => {
      if (baggageKey === LANGFUSE_TRACE_ID_BAGGAGE_KEY) return;

      if (baggageKey.startsWith(LANGFUSE_BAGGAGE_PREFIX)) {
        const spanKey = getSpanKeyFromBaggageKey(baggageKey);

        if (spanKey) {
          const isMergedTags =
            baggageKey == getBaggageKeyForPropagatedKey("tags");

          propagatedAttributes[spanKey] = isMergedTags
            ? baggageEntry.value.split(LANGFUSE_BAGGAGE_TAGS_SEPARATOR)
            : baggageEntry.value;
        }
      }
    });
  }

  // Handle OTEL context values
  const userId = context.getValue(LangfuseOtelContextKeys["userId"]);
  if (userId && typeof userId === "string") {
    const spanKey = getSpanKeyForPropagatedKey("userId");

    propagatedAttributes[spanKey] = userId;
  }

  const sessionId = context.getValue(LangfuseOtelContextKeys["sessionId"]);
  if (sessionId && typeof sessionId === "string") {
    const spanKey = getSpanKeyForPropagatedKey("sessionId");

    propagatedAttributes[spanKey] = sessionId;
  }

  const version = context.getValue(LangfuseOtelContextKeys["version"]);
  if (version && typeof version === "string") {
    const spanKey = getSpanKeyForPropagatedKey("version");

    propagatedAttributes[spanKey] = version;
  }

  const traceName = context.getValue(LangfuseOtelContextKeys["traceName"]);
  if (traceName && typeof traceName === "string") {
    const spanKey = getSpanKeyForPropagatedKey("traceName");

    propagatedAttributes[spanKey] = traceName;
  }

  const tags = context.getValue(LangfuseOtelContextKeys["tags"]);
  if (tags && Array.isArray(tags)) {
    const spanKey = getSpanKeyForPropagatedKey("tags");

    propagatedAttributes[spanKey] = tags;
  }

  const metadata = context.getValue(LangfuseOtelContextKeys["metadata"]);
  if (metadata && typeof metadata === "object" && metadata !== null) {
    for (const [k, v] of Object.entries(metadata)) {
