import { NodeSDK } from '@opentelemetry/sdk-node';
import { LangfuseSpanProcessor } from '@langfuse/otel';
import { propagateAttributes, setActiveTraceIO, setActiveTraceAsPublic } from '@langfuse/tracing';
import { trace } from '@opentelemetry/api';
import * as fs from 'fs';
import * as path from 'path';

async function main() {
  const runId = process.env.ZEALT_RUN_ID;
  if (!runId) {
    console.error('ZEALT_RUN_ID environment variable is not set');
    process.exit(1);
  }

  const sdk = new NodeSDK({
    spanProcessor: new LangfuseSpanProcessor(),
  });

  sdk.start();

  try {
    // Use propagateAttributes to set trace-level fields
    await propagateAttributes({
      traceName: `release-test-${runId}`,
      sessionId: `session-${runId}`,
      userId: `user-${runId}`,
      tags: ['staging', `run-${runId}`],
      release: 'v1.2.3',
      version: 'v1.0.0',
    }, async () => {
      // Start a span within the context to ensure a trace is created
      const tracer = trace.getTracer('my-tracer');
      await tracer.startActiveSpan('main-span', async (span) => {
        // Set public visibility
        setActiveTraceAsPublic();

        // Set input and output
        setActiveTraceIO({
          input: { message: 'Hello Langfuse', runId },
          output: { message: 'Success', status: 200 },
        });

        // Get the trace ID
        const traceId = span.spanContext().traceId;
        if (traceId) {
          const logPath = path.join('/home/user/myproject', 'output.log');
          fs.appendFileSync(logPath, `Trace ID: ${traceId}\n`);
        }

        span.end();
      });
    });
  } catch (error) {
    console.error('Error during trace execution:', error);
  } finally {
    await sdk.shutdown();
  }
}

main().catch(console.error);

