export enum LogLevel {
  /** Not logging anything */
  NONE = 4,
  /** Critical errors that may cause application failure */
  ERROR = 3,
  /** Warning messages for potentially harmful situations */
  WARN = 2,
  /** General informational messages */
  INFO = 1,
