const MAX_RETRY_DELAY = 60000; // in milliseconds
const DEFAULT_MAX_RETRIES = 2;
const JITTER_FACTOR = 0.2; // 20% random jitter

function addPositiveJitter(delay: number): number {
  // Generate a random value between 0 and +JITTER_FACTOR
  const jitterMultiplier = 1 + Math.random() * JITTER_FACTOR;
  return delay * jitterMultiplier;
}

function addSymmetricJitter(delay: number): number {
  // Generate a random value in a JITTER_FACTOR-sized percentage range around delay
  const jitterMultiplier = 1 + (Math.random() - 0.5) * JITTER_FACTOR;
  return delay * jitterMultiplier;
}

function getRetryDelayFromHeaders(
  response: Response,
  retryAttempt: number,
): number {
  // Check for Retry-After header first (RFC 7231), with no jitter
  const retryAfter = response.headers.get("Retry-After");
  if (retryAfter) {
    // Parse as number of seconds...
    const retryAfterSeconds = parseInt(retryAfter, 10);
    if (!isNaN(retryAfterSeconds) && retryAfterSeconds > 0) {
      return Math.min(retryAfterSeconds * 1000, MAX_RETRY_DELAY);
    }

    // ...or as an HTTP date; both are valid
    const retryAfterDate = new Date(retryAfter);
    if (!isNaN(retryAfterDate.getTime())) {
      const delay = retryAfterDate.getTime() - Date.now();
      if (delay > 0) {
        return Math.min(Math.max(delay, 0), MAX_RETRY_DELAY);
      }
    }
  }

  // Then check for industry-standard X-RateLimit-Reset header, with positive jitter
  const rateLimitReset = response.headers.get("X-RateLimit-Reset");
  if (rateLimitReset) {
    const resetTime = parseInt(rateLimitReset, 10);
    if (!isNaN(resetTime)) {
      // Assume Unix timestamp in epoch seconds
      const delay = resetTime * 1000 - Date.now();
      if (delay > 0) {
        return addPositiveJitter(Math.min(delay, MAX_RETRY_DELAY));
      }
    }
  }

  // Fall back to exponential backoff, with symmetric jitter
  return addSymmetricJitter(
    Math.min(INITIAL_RETRY_DELAY * Math.pow(2, retryAttempt), MAX_RETRY_DELAY),
  );
}

export async function requestWithRetries(
  requestFn: () => Promise<Response>,
  maxRetries: number = DEFAULT_MAX_RETRIES,
